{"engines/analysis/field_fit.py": "def fit_field(width, height, coast, samples):
    """Return the public field list sorted by (y, x), with one
    {x, y, dx, dy, error, gap} row for each sea cell.

    coast and samples retain their public shapes. Use the published
    displacement, weighted-error, tie, second distinct vector and
    no-observation rules. Preserve inputs.
    """
    coast_set = set(tuple(c) for c in coast)
    by_cell = {}
    for s in samples:
        by_cell.setdefault((s["x"], s["y"]), []).append(s)

    field = []
    for y in range(height):
        for x in range(width):
            if (x, y) in coast_set:
                continue
            cell_samples = by_cell.get((x, y), [])
            if not cell_samples:
                field.append({"x": x, "y": y, "dx": 0, "dy": 0, "error": 0, "gap": 0})
                continue

            # Weighted L1 error for every candidate vector.
            errors = {}
            for dx in (-1, 0, 1):
                for dy in (-1, 0, 1):
                    err = 0
                    for s in cell_samples:
                        err += s["weight"] * (abs(dx - s["dx"]) + abs(dy - s["dy"]))
                    errors[(dx, dy)] = err

            # Lexicographically smallest (dx, dy) among minimum error.
            best = min(errors, key=lambda v: (errors[v], v[0], v[1]))
            best_err = errors[best]

            # Second distinct vector's lowest error.
            distinct = [e for v, e in errors.items() if v != best]
            second = min(distinct) if distinct else best_err
            gap = second - best_err

            field.append({
                "x": x, "y": y,
                "dx": best[0], "dy": best[1],
                "error": best_err, "gap": gap,
            })

    field.sort(key=lambda r: (r["y"], r["x"]))
    return field
